"""Roman numeral conversion: integers 1–3999 and back."""


def to_roman(n):
    """Convert an integer in [1, 3999] to a standard Roman numeral string.

    Raises ValueError for non-integers or values outside the valid range.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("argument must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("value must be between 1 and 3999 inclusive")

    _mapping = (
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    )

    parts = []
    for value, symbol in _mapping:
        while n >= value:
            parts.append(symbol)
            n -= value
    return "".join(parts)


def from_roman(s):
    """Convert a standard subtractive Roman numeral string to its integer value.

    Raises ValueError for any string that is not a well-formed Roman numeral.
    """
    if not isinstance(s, str):
        raise ValueError("argument must be a string")

    roman_values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

    # Quick validation: only allowed characters
    if not all(ch in roman_values for ch in s):
        raise ValueError(f"invalid character in '{s}'")

    if len(s) == 0:
        raise ValueError("empty string")

    # Parse numeric value
    total = 0
    prev = 0
    for ch in reversed(s):
        val = roman_values[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val

    # Round-trip check: re-encode and compare — this catches IIII, VV, IC, XM, etc.
    if to_roman(total) != s:
        raise ValueError(f"'{s}' is not a well-formed Roman numeral")

    return total
